#include <cstdio>
#include <cstdlib>
#include <limits>
#include "engine/gameplay/option_mouse_geometry.hpp"
namespace {unsigned checks=0;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"Options mouse geometry: %s\n",why);std::abort();}}}
int main(){using namespace gf;OptionMouseGeometry g;OptionMouseTarget hit;const OptionMouseTarget row{OptionMouseArea::Settings,1,-1,0},value{OptionMouseArea::Settings,1,3,0};check(!g.hit(20,20,OptionMouseArea::Settings,&hit),"unpublished geometry cannot hit");g.begin(OptionMouseArea::Settings);check(g.screen(10,10,110,50,row)&&g.screen(60,10,80,50,value)&&!g.hit(70,30,OptionMouseArea::Settings,&hit)&&g.finish(),"actual draw completion publishes geometry");check(g.hit(30,30,OptionMouseArea::Settings,&hit)&&hit.row==1&&hit.value==-1,"row target");check(g.hit(70,30,OptionMouseArea::Settings,&hit)&&hit.value==3,"specific value wins general row");check(!g.hit(70,30,OptionMouseArea::More,&hit)&&hit.area==OptionMouseArea::None,"stale-page request refuses and clears output");check(!g.hit(-1,20,OptionMouseArea::Settings,&hit)&&!g.hit(640,20,OptionMouseArea::Settings,&hit)&&!g.hit(std::numeric_limits<f32>::quiet_NaN(),20,OptionMouseArea::Settings,&hit),"invalid pointer domain");g.begin(OptionMouseArea::Details);check(!g.hit(70,30,OptionMouseArea::Settings,&hit),"modal invalidates all underlying regions");check(g.screen(120,360,300,380,{OptionMouseArea::Details,-1,-1,0x100})&&g.finish()&&g.hit(180,370,OptionMouseArea::Details,&hit)&&hit.left_pressed==0x100,"modal footer only");check(!g.hit(180,250,OptionMouseArea::Details,&hit),"blank modal body is not a guessed button");
    for(unsigned bad=0;bad<5;++bad){g.begin(OptionMouseArea::Settings);auto q=std::array<std::array<f32,2>,4>{{{10,10},{110,10},{110,50},{10,50}}};auto target=row;if(bad==0)q[2]=q[1];else if(bad==1)q[2]={40,20};else if(bad==2)q[0][0]=std::numeric_limits<f32>::infinity();else if(bad==3)target.area=OptionMouseArea::More;else target.row=10;check(!g.add(q,target)&&!g.finish()&&g.regions().empty(),"bad quad/action rejects entire plan");}
    Camera camera;camera.eye[0]=camera.eye[1]=camera.eye[2]=0;camera.target[0]=camera.target[1]=0;camera.target[2]=-1;camera.up[0]=camera.up[2]=0;camera.up[1]=1;camera.near_plane=1;camera.far_plane=100;camera.fov_y_degrees=60;camera.viewport_width=640;camera.viewport_height=480;const std::array<std::array<f32,3>,4> local={{{-1,1,-10},{1,1,-10},{1,-1,-10},{-1,-1,-10}}};g.begin(OptionMouseArea::Settings);check(g.world(camera,Mat4{},local,row)&&g.finish()&&g.hit(320,240,OptionMouseArea::Settings,&hit),"same camera/affine projection as drawn UI");g.begin(OptionMouseArea::Settings);camera.viewport_width=960;check(!g.world(camera,Mat4{},local,row),"unmapped drawable-size coordinates refused");g.begin(OptionMouseArea::Settings);for(unsigned i=0;i<64;++i)check(g.screen(1,1,2,2,row),"bounded region budget");check(!g.screen(1,1,2,2,row)&&!g.finish(),"budget failure invalidates rather than partial target publication");std::printf("Options projected word/bar/modal coverage: %u checks PASS\n",checks);return 0;}
